-- ============================================================
-- SEED du moteur officiel Cameroun (référentiel MINEDUB + MINESEC).
-- GÉNÉRÉ par scripts/build-officiel-seed.mjs — NE PAS ÉDITER À LA MAIN.
-- Rejouable (INSERT … ON CONFLICT). Chargé au boot par server/db.js.
-- ============================================================


ON CONFLICT (id) DO UPDATE SET nom = EXCLUDED.nom;

ON CONFLICT (id) DO UPDATE SET nom = EXCLUDED.nom, niveau = EXCLUDED.niveau, cycle_id = EXCLUDED.cycle_id;

ON CONFLICT (id) DO UPDATE SET numero = EXCLUDED.numero;

ON CONFLICT (id) DO UPDATE SET numero = EXCLUDED.numero, trimestre_id = EXCLUDED.trimestre_id;

ON CONFLICT (id) DO UPDATE
  SET nom = EXCLUDED.nom, coefficient = EXCLUDED.coefficient,
      optionnelle = EXCLUDED.optionnelle, ordre = EXCLUDED.ordre;

VALUES ('9abce227-12a3-48a4-8479-ec262dcf6175', 'MINESEC — Référentiel APC Premier cycle (6e–3e)', 'Bulletins officiels APC ordinaires (DOCX MINESEC)', true)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (classe_id, trimestre_id, matiere_id, ordre) DO UPDATE
  SET intitule = EXCLUDED.intitule,
      coefficient = EXCLUDED.coefficient,
      actif = true,
      referentiel_version_id = EXCLUDED.referentiel_version_id;

ON CONFLICT (classe_id, matiere_id) DO UPDATE
  SET coefficient = EXCLUDED.coefficient, ordre = EXCLUDED.ordre, optionnelle = EXCLUDED.optionnelle;

ON CONFLICT (id) DO UPDATE SET nom = EXCLUDED.nom, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE
  SET nom = EXCLUDED.nom, categorie = EXCLUDED.categorie,
      description = EXCLUDED.description, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE SET nom=EXCLUDED.nom, categorie=EXCLUDED.categorie, description=EXCLUDED.description, ordre=EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE SET nom=EXCLUDED.nom, code=EXCLUDED.code, domaine_apprentissage=EXCLUDED.domaine_apprentissage, ordre=EXCLUDED.ordre;

VALUES ('c4ab6236-7eac-46c5-a626-abdf221cd0c7', 'Arrêté MINESEC 092/22 du 07/03/2022', 'Arrêté n°092/22/MINESEC du 07 mars 2022', true)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (serie_id, classe_id, matiere_id) DO UPDATE
  SET groupe_id=EXCLUDED.groupe_id, coefficient=EXCLUDED.coefficient, charge_horaire=EXCLUDED.charge_horaire,
      obligatoire=EXCLUDED.obligatoire, actif=true, referentiel_version_id=EXCLUDED.referentiel_version_id;

ON CONFLICT (id) DO UPDATE SET nom = EXCLUDED.nom, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE
  SET code = EXCLUDED.code, intitule = EXCLUDED.intitule, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE SET nom = EXCLUDED.nom, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE
  SET cycle_id = EXCLUDED.cycle_id, nom = EXCLUDED.nom, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE
  SET code = EXCLUDED.code, intitule = EXCLUDED.intitule,
      domaine = EXCLUDED.domaine, ordre = EXCLUDED.ordre;

ON CONFLICT (id) DO UPDATE
  SET nom = EXCLUDED.nom, poids = EXCLUDED.poids, ordre = EXCLUDED.ordre;

-- Seuils alignés sur le carnet officiel MINEDUB (p.2) : A+ 18-20/20, A 15-17/20,
-- ECA 11-14/20, NA 0-10/20 → 90% / 75% / 55% / 0%.
ON CONFLICT (id) DO UPDATE
  SET cote = EXCLUDED.cote, libelle = EXCLUDED.libelle, seuil_min = EXCLUDED.seuil_min, ordre = EXCLUDED.ordre;

